import sys
import weakref
import pickle

# Test Grouper class directly without importing matplotlib
class Grouper:
    def __init__(self, init=()):
        self._mapping = weakref.WeakKeyDictionary()
        for x in init:
            self._mapping[x] = weakref.WeakSet([x])

    def __getstate__(self):
        return {
            '_mapping': {k: list(v) for k, v in self._mapping.items()},
        }

    def __setstate__(self, state):
        self._mapping = weakref.WeakKeyDictionary()
        for k, vs in state['_mapping'].items():
            self._mapping[k] = weakref.WeakSet(vs)

    def __contains__(self, item):
        return item in self._mapping

    def join(self, a, *args):
        mapping = self._mapping
        if a not in mapping:
            mapping[a] = weakref.WeakSet([a])
        set_a = mapping[a]
        for arg in args:
            if arg not in mapping:
                mapping[arg] = weakref.WeakSet([arg])
            set_b = mapping[arg]
            if set_b is not set_a:
                if len(set_b) > len(set_a):
                    set_a, set_b = set_b, set_a
                items_b = list(set_b)
                for item in items_b:
                    set_a.add(item)
                    mapping[item] = set_a
                set_b.clear()

    def joined(self, a, b):
        if a not in self._mapping or b not in self._mapping:
            return False
        return self._mapping[a] is self._mapping[b]

    def remove(self, a):
        set_a = self._mapping.pop(a, None)
        if set_a:
            set_a.clear()

    def __iter__(self):
        unique_groups = {id(group): group for group in self._mapping.values()}
        for group in unique_groups.values():
            yield list(group)

    def get_siblings(self, a):
        if a in self._mapping:
            return list(self._mapping[a])
        return [a]

